            } else {
                log.debug("Xpj42 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
            }
        } else {
            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
        }


        try {
            Xtw92 orderBid = orderBidQueryService.findByOrderId(orderId)
