353	    public Xfr60 process(Xfr60 orderShipment) throws Exception {
354	        String trackingNumber = orderShipment.getTrackingNumber();
355	        Long shipmentId = orderShipment.getId();
356	
357	        if (trackingNumber == null || trackingNumber.isBlank()) {
358	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
359	            throw new Xzn53Exception(Xzn53ErrorCode.TRACKING_NUMBER_INVALID);
360	        }
361	
362	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
363	                shipmentId, trackingNumber, orderShipment.getStatus());
364	
365	        Page page = null;
366	        try {
367	
368	            page = browserManager.newPage();
369	            if (page == null) {
370	                throw new Xzn53Exception(Xzn53ErrorCode.BROWSER_INITIALIZATION_ERROR);
371	            }
372	
373	
374	            page.setDefaultTimeout(TIMEOUT_MS);
375	
376	
377	            String url = TRACKING_URL_PREFIX + trackingNumber;
378	            log.debug("배송 조회 페이지로 이동: {}", url);
379	            page.navigate(url);
380	
381	
382	            log.debug("배송 상태 테이블 로드 대기");
383	            page.waitForSelector(STATUS_SELECTOR);
384	
385	
386	            String renderedHtml = page.content();
387	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
388	
389	
390	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
391	            Xzn53Status newStatus = mapToShipmentStatus(statusText);
392	
393	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
394	                    shipmentId, statusText, newStatus);
395	
396	
397	            if (orderShipment.getStatus() == newStatus) {
398	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
399	                        shipmentId, newStatus);
400	                return orderShipment;
401	            }
402	
403	
404	            if (newStatus == Xzn53Status.DELIVERED) {
405	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
406	                        shipmentId, orderShipment.getOrder().getId());
407	
408	
409	                orderShipment.updateStatus(Xzn53Status.DELIVERED);
410	
411	
412	                orderService.completeOrder(orderShipment.getOrder().getId());
413	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
414	
415	            } else if (newStatus == Xzn53Status.OUT_FOR_DELIVERY) {
416	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
417	                orderShipment.updateStatus(Xzn53Status.OUT_FOR_DELIVERY);
418	
419	            } else {
420	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
421	                orderShipment.updateStatus(Xzn53Status.IN_TRANSIT);
422	            }
423	
424	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
425	                    shipmentId, orderShipment.getStatus());
426	
427	            return orderShipment;
428	
429	        } catch (Exception e) {
430	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
431	                    shipmentId, trackingNumber, e.getMessage(), e);
432	
433	
434	            if (!(e instanceof Xzn53Exception)) {
435	                throw new Xzn53Exception(
436	                        Xzn53ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
437	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
438	                        e
439	                );
440	            }
441	            throw e;
442	        } finally {
443	
444	            if (page != null) {
445	                try {
446	                    page.close();
447	                    log.debug("페이지 리소스 해제 완료");
448	                } catch (Exception e) {
449	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
450	                }
451	            }
452	        }
453	    }
